fn keep(s: &Snapshot, user: u64, p: &Pdu, filter_event_type: Option<Kind>, filter_rel_type: Option<RelType>) -> bool {
    let type_ok = match filter_event_type {
        None => true,
        Some(k) => kind_eq(k, p.kind),
