filters.is_forbidden_remote_server_name.code:
pub fn is_forbidden_remote_server_name(c: &Config, server: u64) -> bool {
    if server == c.server_name {
        return false;
    }
    let deny_list_active = c.forbidden_remote_server_names.len() != 0;
    let allow_list_active = c.allowed_remote_server_names.len() != 0;
    if deny_list_active && contains_u64(&c.forbidden_remote_server_names, server) {
        return true;
    }
    if allow_list_active && !contains_u64(&c.allowed_remote_server_names, server) {
        return true;
    }
    false
}

filters.matches.code:
pub fn matches(filter: &Filter, p: &Pdu) -> bool {
    if !matches_sender(p, filter) {
        return false;
    }
    if !matches_room(p, filter) {
        return false;
    }
    if !matches_type(p, filter) {
        return false;
    }
    if !matches_url(p, filter) {
        return false;
    }
    true
}

filters.matches_room.code:
pub fn matches_room(p: &Pdu, filter: &Filter) -> bool {
    if contains_u64(&filter.not_rooms, p.room) {
        return false;
    }
    match &filter.rooms {
        Some(rooms) => contains_u64(rooms, p.room),
        None => true,
    }
}

filters.matches_sender.code:
pub fn matches_sender(p: &Pdu, filter: &Filter) -> bool {
    if contains_u64(&filter.not_senders, p.sender) {
        return false;
    }
    match &filter.senders {
        Some(senders) => contains_u64(senders, p.sender),
        None => true,
    }
}

filters.matches_type.code:
pub fn matches_type(p: &Pdu, filter: &Filter) -> bool {
    if any_kind(&filter.not_types, p.kind) {
        return false;
    }
    match &filter.types {
        Some(types) => any_kind(types, p.kind),
        None => true,
    }
}

filters.matches_url.code:
pub fn matches_url(p: &Pdu, filter: &Filter) -> bool {
    match filter.url_filter {
        UrlFilter::Any => true,
        UrlFilter::WithUrl => p.has_url,
        UrlFilter::WithoutUrl => !p.has_url,
    }
}

membership_eq.code:
pub fn membership_eq(a: Membership, b: Membership) -> bool {
    match a {
        Membership::Join => matches!(b, Membership::Join),
        Membership::Invite => matches!(b, Membership::Invite),
        Membership::Leave => matches!(b, Membership::Leave),
        Membership::Ban => matches!(b, Membership::Ban),
        Membership::Knock => matches!(b, Membership::Knock),
        Membership::Custom(x) => match b {
            Membership::Custom(y) => x == y,
            _ => false,
        },
    }
}

rel_type_eq.code:
pub fn rel_type_eq(a: RelType, b: RelType) -> bool {
    match a {
        RelType::Annotation => matches!(b, RelType::Annotation),
        RelType::Reference => matches!(b, RelType::Reference),
        RelType::Replacement => matches!(b, RelType::Replacement),
        RelType::Thread => matches!(b, RelType::Thread),
        RelType::Custom(x) => match b {
            RelType::Custom(y) => x == y,
            _ => false,
        },
    }
}

