svc_relations.inc_bits.code:
pub fn inc_bits(c: i64, dir: Dir) -> u64 {
    if c > 0 {
        match dir {
            Dir::Forward => (c as u64) + 1,
            Dir::Backward => (c as u64) - 1,
        }
    } else {
        match dir {
            Dir::Forward => c.saturating_add(1) as u64,
            Dir::Backward => c.saturating_sub(1) as u64,
        }
    }
}

