fn matches_room<E: Event>(event: &E, filter: &RoomEventFilter) -> bool {
	if filter
		.not_rooms
		.iter()
		.any(is_equal_to!(event.room_id()))
	{
		return false;
	}

	if let Some(rooms) = filter.rooms.as_ref()
		&& !rooms.iter().any(is_equal_to!(event.room_id()))
	{
		return false;
	}

	true
}

